-- 앞서 넣은 Spotify 작품·곡 링크를 고친 규칙으로 다시 고른 결과에 맞춘다.
-- 자료: seed_pipeline/curation/piece-album-links-2026-11-08/. 고친 규칙: 발췌·하이라이트 음반,
-- 재즈 편곡·태교·수면용 음반, 다른 작곡가 작품번호(HWV·BWV·RV 등)가 붙은 트랙,
-- 연주자 이름에 걸린 작곡가 성, 두 작품 앨범에서 다른 작품 트랙만 받은 경우를 거른다.
-- 작품 43곳(그중 비움 10곳), 곡 112곡(새로 붙임 12곡, 뺌 13곡).
-- 지금 값이 앞서 넣은 값과 같을 때만 쓴다. 두 번 넣어도 같다.

CREATE TEMPORARY TABLE tmp_fix_piece_spotify (
    piece_id INT NOT NULL PRIMARY KEY,
    old_url VARCHAR(500) NULL,
    url VARCHAR(500) NULL
);

UPDATE pieces piece
JOIN tmp_fix_piece_spotify link ON link.piece_id = piece.id
SET piece.spotify_url = link.url
WHERE (link.old_url IS NULL AND (piece.spotify_url IS NULL OR piece.spotify_url = ''))
    OR piece.spotify_url = link.old_url;

DROP TEMPORARY TABLE tmp_fix_piece_spotify;

CREATE TEMPORARY TABLE tmp_fix_part_spotify (
    part_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
    piece_id INT NOT NULL,
    sequence_number INT NOT NULL,
    old_url VARCHAR(500) NULL,
    url VARCHAR(500) NULL
);

UPDATE piece_parts part
JOIN tmp_fix_part_spotify link
    ON link.part_id = part.id
    AND link.piece_id = part.piece_id
    AND link.sequence_number = part.sequence_number
SET part.spotify_url = link.url
WHERE part.parent_part_id IS NULL
    AND ((link.old_url IS NULL AND (part.spotify_url IS NULL OR part.spotify_url = ''))
        OR part.spotify_url = link.old_url);

DROP TEMPORARY TABLE tmp_fix_part_spotify;
